gn-items:flex-end;justify-content:space-between;gap:24px;margin-bottom:22px}.asset-content-heading h2{margin:0;font-size:29px}.asset-content-heading p:not(.assets-eyebrow){margin:6px 0 0;color:var(--muted);font-size:12px}.asset-search{display:flex;align-items:center;gap:8px;width:190px;padding:8px 10px;border:1px solid var(--line);border-radius:4px;color:#888}.asset-search input{width:100%;border:0;outline:0;background:none;color:var(--ink);font:12px Inter,Arial,sans-serif}.asset-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:24px 16px}.asset-card{min-width:0}.asset-preview{display:grid;place-items:center;width:100%;aspect-ratio:1.12/1;padding:20px;border:1px solid #efede9;background:#f6f5f3;cursor:zoom-in}.asset-card:nth-child(even) .asset-preview{background:#141414;border-color:#141414}.asset-preview img{display:block;max-width:100%;max-height:100%;object-fit:contain}.asset-caption{display:flex;justify-content:space-between;gap:12px;padding-top:11px}.asset-caption h3{margin:0;font-size:14px;letter-spacing:-.02em}.asset-caption p{margin:4px 0;color:var(--muted);font-size:11px;white-space:pre-wrap}.asset-caption small{display:block;margin-top:6px;color:#99948d;font-size:10px}.asset-caption>a{display:grid;place-items:center;flex:none;width:30px;height:30px;border:1px solid var(--line);border-radius:50%;color:var(--ink);text-decoration:none}.asset-empty{display:grid;justify-items:center;align-content:center;min-height:220px;padding:25px;text-align:center;color:var(--muted)}.asset-empty>.iconify{font-size:28px}.asset-empty h3{margin:11px 0 3px;font-size:17px}.asset-empty p{margin:0;font-size:12px}.prompt-card{margin-top:40px;padding:23px;border:1px solid var(--line);background:#fbfaf7}.prompt-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:15px}.prompt-heading h2{margin:0;font-size:19px}.prompt-heading p:not(.assets-eyebrow){margin:5px 0 0;color:var(--muted);font-size:11px}.copy-prompt{flex:none;padding:8px 12px;font-size:11px}.prompt-card pre{margin:20px 0 0;padding:17px;max-height:280px;overflow:auto;background:#f1efeb;color:#403e3b;font:12px/1.7 ui-monospace,SFMono-Regular,Menlo,monospace;white-space:pre-wrap}.prompt-placeholder{padding:14px;background:#f1efeb;color:var(--muted);font-size:12px}.assets-message{margin:15px 0 0;padding:10px 12px;border:1px solid #dac8c2;background:#fbf3f0;color:#6e3d31;font-size:12px}.assets-message.success{border-color:#d9ded0;background:#f4f6ef;color:#4b5940}.asset-form{max-width:780px;margin:22px 0;padding:22px;border:1px solid var(--line);background:#fbfaf7}.asset-form-heading{display:flex;align-items:flex-start;justify-content:space-between}.asset-form-heading h2{margin:0;font-size:21px}.asset-icon-button{border:0;background:none;color:var(--ink);font-size:24px;cursor:pointer}.asset-fields{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin:18px 0}.asset-fields label{display:grid;gap:6px;color:#5e5a55;font-size:11px}.asset-fields .wide{grid-column:1/-1}.asset-fields input,.asset-fields textarea,.asset-fields select{width:100%;padding:10px;border:1px solid var(--line);border-radius:3px;background:#fffefa;color:var(--ink);font:12px Inter,Arial,sans-serif}.asset-file small{color:var(--muted)}.asset-lightbox{position:fixed;inset:0;z-index:100;display:flex;align-items:center;justify-content:center;gap:35px;padding:50px;background:#000e;color:#fff}.asset-lightbox>img{max-width:min(68vw,900px);max-height:82vh;object-fit:contain}.asset-lightbox>div{width:min(250px,25vw)}.asset-lightbox h2{color:#fff}.asset-lightbox p{color:#aaa;font-size:12px}.asset-lightbox a,.remove-asset{display:inline-flex;align-items:center;gap:7px;margin-top:12px;padding:9px 12px;border:1px solid #ffffff55;border-radius:3px;background:transparent;color:#fff;text-decoration:none;font:11px Inter,Arial,sans-serif;cursor:pointer}.asset-close{position:absolute;top:18px;right:24px;border:0;background:none;color:#fff;font-size:34px;cursor:pointer}
